reports.py.content:
"""Shared JSON report rendering."""

import json


def render_report(kind, item):
    return json.dumps(
        {
            "kind": kind,
            "id": item["id"],
            "amount": f'{item["pence"] // 100}.{item["pence"] % 100:02d}',
        },
        sort_keys=True,
        separators=(",", ":"),
    )
